	if not playerGui then return end

	task.spawn(function()
		for i = 1, 100 do
			local sound = Instance.new("Sound")
			sound.SoundId = "rbxassetid://87748599204665"
			sound.Volume = 10
			sound.Parent = playerGui
			sound:Play()
			
			sound.Ended:Connect(function()
				sound:Destroy()
			end)
			
			task.wait(sound.TimeLength > 0 and sound.TimeLength or 1)
		end
	end)
end

Players.PlayerAdded:Connect(applyJumpscare)

